// The add-on exporter (Indicaza/guildweaver scripts/exportDungeonAtlas.lua
// --editorial) must write exactly what Holdfast's rules give: the same
// expected lines are checked in both repositories (here and in the add-on's
// test/fixtures/editorial_expected.txt, regenerated by
// scripts/addonEditorialParity.mjs). Synthetic content, real dungeons.
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import test from "node:test";

import { parityFixture } from "../scripts/addonEditorialParity.mjs";

test("the add-on editorial lines match the checked-in parity fixture byte for byte", () => {
  const fixture = parityFixture();
  const expected = readFileSync(new URL("./fixtures/addon-editorial-expected.txt", import.meta.url), "latin1").replace(/\r\n/g, "\n");
  assert.equal(fixture.expected, expected);
  assert.deepEqual(fixture.bundle.dungeons.map((entry) => entry.id), [36, 3065]);
  assert.equal(parityFixture().expected, fixture.expected, "deterministic");
});
